use godly_protocol::types::RichGridData;
use godly_terminal_surface::{
    atlas_shader::{AtlasPipeline, AtlasShaderProgram},
    atlas_vertex_builder::{self, CellVertex},
    font_metrics::FontMetrics,
    glyph_atlas::GlyphAtlas,
    glyph_cache::GlyphKey,
    glyph_rasterizer::GlyphRasterizer,
    Color,
};

use crate::ui::builder::{TextCommand, TextCompositeMode, TextFontKind};

pub struct TerminalRenderer {
    pipeline: AtlasPipeline,
    glyph_atlas: GlyphAtlas,
    rasterizer: Box<dyn GlyphRasterizer>,
    /// Optional proportional sans-serif rasterizer for UI chrome labels.
    ui_rasterizer: Option<Box<dyn GlyphRasterizer>>,
    /// Optional serif rasterizer for rich UI copy (e.g. poem panel italics).
    ui_serif_rasterizer: Option<Box<dyn GlyphRasterizer>>,
    font_metrics: FontMetrics,
    /// Average advance width of the UI font (for layout estimation).
    ui_avg_advance: f32,
    default_fg: Color,
    default_bg: Color,
}

impl TerminalRenderer {
    pub fn new(
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        format: wgpu::TextureFormat,
        font_metrics: FontMetrics,
        rasterizer: Box<dyn GlyphRasterizer>,
    ) -> Self {
        let pipeline = AtlasPipeline::new(device, queue, format);
        let phys = font_metrics.scaled_for_render();
        let glyph_atlas = GlyphAtlas::new(phys.cell_width, phys.cell_height, phys.baseline_offset);

        Self {
            pipeline,
            glyph_atlas,
            rasterizer,
            ui_rasterizer: None,
            ui_serif_rasterizer: None,
            font_metrics,
            ui_avg_advance: 0.0,
            default_fg: Color::new(0.788, 0.820, 0.851, 1.0), // GitHub Dark Text #c9d1d9
            default_bg: Color::new(0.055, 0.063, 0.090, 1.0), // GitHub Dark Base #0e1017
        }
    }

    /// Set the proportional UI font rasterizer (e.g., Segoe UI).
    pub fn set_ui_rasterizer(&mut self, mut rasterizer: Box<dyn GlyphRasterizer>) {
        let phys = self.font_metrics.scaled_for_render();
        let metrics = rasterizer.measure(phys.font_size);
        self.ui_avg_advance = metrics.average_advance;
        self.ui_rasterizer = Some(rasterizer);
    }

    pub fn set_ui_serif_rasterizer(&mut self, rasterizer: Box<dyn GlyphRasterizer>) {
        self.ui_serif_rasterizer = Some(rasterizer);
    }

    /// Average advance width of the UI proportional font.
    pub fn ui_avg_advance(&self) -> f32 {
        self.ui_avg_advance
    }

    /// Prepare GPU resources (atlas texture upload, vertex buffer) BEFORE the render pass.
    ///
    /// Renders both terminal grid content and UI chrome text through the
    /// same glyph atlas pipeline for consistent ClearType quality.
    pub fn prepare(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        grid: Option<&RichGridData>,
        full_width: u32,
        full_height: u32,
        offset_x: f32,
        offset_y: f32,
        terminal_w: f32,
        terminal_h: f32,
        ui_text: &[TextCommand],
    ) {
        let mut vertices = if let Some(grid) = grid {
            atlas_vertex_builder::build_vertices(
                grid,
                &mut self.glyph_atlas,
                &self.font_metrics,
                &mut *self.rasterizer,
                self.default_fg,
                self.default_bg,
                full_width,
                full_height,
                offset_x,
                offset_y,
                terminal_w,
                terminal_h,
            )
        } else {
            Vec::new()
        };

        // Rasterize UI chrome text through the same atlas.
        // UI text uses transparent bg (alpha=0) to trigger grayscale AA mode
        // in the atlas shader, so text alpha-composites cleanly over gradient
        // and SDF-rounded backgrounds drawn by the quad pipeline.
        let phys = self.font_metrics.scaled_for_render();
        let vw = full_width as f32;
        let vh = full_height as f32;
        let transparent_bg = [0.0f32, 0.0, 0.0, 0.0];

        for cmd in ui_text {
            let draw_scale = cmd.scale * cmd.raster_scale;
            let font_size = phys.font_size * draw_scale;
            let use_variable_advance = !matches!(cmd.font_kind, TextFontKind::TerminalMono);
            let use_serif = matches!(cmd.font_kind, TextFontKind::UiSerif);
            let mut fallback_x = cmd.x;

            for (index, ch) in cmd.text.chars().enumerate() {
                let entry = match cmd.font_kind {
                    TextFontKind::TerminalMono => {
                        let key = GlyphKey::new(ch, font_size, cmd.bold, cmd.italic);
                        self.glyph_atlas
                            .get_or_insert(key, &mut *self.rasterizer, font_size)
                    }
                    TextFontKind::UiMono => {
                        let key = GlyphKey::new_font(ch, font_size, cmd.bold, cmd.italic, 3);
                        self.glyph_atlas
                            .get_or_insert(key, &mut *self.rasterizer, font_size)
                    }
                    TextFontKind::UiSans => {
                        let Some(rast) = self.ui_rasterizer.as_mut() else {
                            continue;
                        };
                        let key = GlyphKey::new_font(ch, font_size, cmd.bold, cmd.italic, 1);
                        self.glyph_atlas.get_or_insert(key, &mut **rast, font_size)
                    }
                    TextFontKind::UiSerif => {
                        let Some(rast) = self
                            .ui_serif_rasterizer
                            .as_mut()
                            .or(self.ui_rasterizer.as_mut())
                        else {
                            continue;
                        };
                        let key = GlyphKey::new_font(ch, font_size, cmd.bold, cmd.italic, 2);
                        self.glyph_atlas.get_or_insert(key, &mut **rast, font_size)
                    }
                };

                let px = cmd
                    .glyph_offsets
                    .get(index)
                    .map_or(fallback_x, |offset| cmd.x + *offset);
                let py = cmd.y;
                // For proportional font, use actual glyph slot width from UV;
                // for monospace, use cell_width.
                let pw = if use_variable_advance {
                    // Slot width = atlas slot pixel width from UV coords
                    (entry.u1 - entry.u0) * self.glyph_atlas.atlas_width() as f32
                } else {
                    phys.cell_width * draw_scale
                };
                let ph = phys.cell_height * draw_scale;

                let x0 = px / vw * 2.0 - 1.0;
                let y0 = 1.0 - py / vh * 2.0;
                let x1 = (px + pw) / vw * 2.0 - 1.0;
                let y1 = 1.0 - (py + ph) / vh * 2.0;

                // 6 vertices (2 triangles)
                let v = |pos: [f32; 2], uv: [f32; 2]| CellVertex {
                    position: pos,
                    uv,
                    fg_color: cmd.fg,
                    bg_color: match cmd.composite {
                        TextCompositeMode::FlatBackground => [cmd.bg[0], cmd.bg[1], cmd.bg[2], 1.0],
                        TextCompositeMode::MixedBackground => transparent_bg,
                    },
                };
                let tl = [x0, y0];
                let tr = [x1, y0];
                let bl = [x0, y1];
                let br = [x1, y1];
                let uv_tl = [entry.u0, entry.v0];
                let uv_br = [entry.u1, entry.v1];
                let uv_tr = [uv_br[0], uv_tl[1]];
                let uv_bl = [uv_tl[0], uv_br[1]];

                vertices.push(v(tl, uv_tl));
                vertices.push(v(tr, uv_tr));
                vertices.push(v(bl, uv_bl));
                vertices.push(v(tr, uv_tr));
                vertices.push(v(bl, uv_bl));
                vertices.push(v(br, uv_br));

                if cmd.glyph_offsets.is_empty() {
                    fallback_x += (if use_variable_advance || use_serif {
                        entry.advance
                    } else {
                        phys.cell_width
                    }) * draw_scale;
                }
            }
        }

        if vertices.is_empty() {
            return;
        }

        let atlas_update = self.glyph_atlas.take_dirty_data();
        let program = AtlasShaderProgram {
            vertices,
            atlas_update,
            viewport_size: (full_width, full_height),
        };
        let primitive = program.build_primitive();
        primitive.prepare(&mut self.pipeline, device, queue);
    }

    /// Draw the prepared terminal content into the render pass.
    pub fn draw(&self, render_pass: &mut wgpu::RenderPass<'_>) {
        // AtlasPipeline stores vertex_count from prepare; draw uses the stored pipeline state
        // We need a dummy primitive to call draw - reuse the pipeline's stored vertex count
        let primitive = godly_terminal_surface::atlas_shader::AtlasShaderProgram {
            vertices: vec![],
            atlas_update: None,
            viewport_size: (0, 0),
        }
        .build_primitive();
        primitive.draw(&self.pipeline, render_pass);
    }

    pub fn font_metrics(&self) -> &FontMetrics {
        &self.font_metrics
    }
}

# DirectWrite ClearType Rendering Implementation Plan

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** Wire the existing DirectWrite ClearType rasterizer into the pixel rendering pipeline so terminal text uses Windows-native subpixel rendering.

**Architecture:** The `DirectWriteRasterizer` already exists and produces ClearType 3x1 RGB bitmaps. We need to: (1) make it implement the `GlyphRasterizer` trait so it's interchangeable with `SwashRasterizer`, (2) use it on Windows in `app.rs`, and (3) enable the pixel renderer by default. The existing `blit_subpixel()` compositing path will automatically activate once glyphs arrive as `SubpixelRgb`.

**Tech Stack:** Rust, Windows DirectWrite API (`windows` crate 0.58), iced framework

**Refs:** GitHub Issue #841

---

## File Structure

| File | Action | Responsibility |
|------|--------|---------------|
| `terminal-surface/src/directwrite_rasterizer.rs` | Modify | Add `GlyphRasterizer` trait impl, bold/italic font face support |
| `terminal-surface/src/lib.rs` | No change | Already exports `directwrite_rasterizer` under `#[cfg(windows)]` |
| `iced-shell/src/app.rs` | Modify | Use DirectWrite on Windows, enable pixel renderer, load font weights |
| `terminal-surface/src/glyph_rasterizer.rs` | No change | Trait already supports `SubpixelRgb` format |
| `terminal-surface/src/pixel_renderer.rs` | No change | `blit_subpixel()` already handles `SubpixelRgb` glyphs |

All paths relative to `src-tauri/native/`.

---

### Task 1: Implement `GlyphRasterizer` trait for `DirectWriteRasterizer`

**Files:**
- Modify: `terminal-surface/src/directwrite_rasterizer.rs`

The `DirectWriteRasterizer` has its own API (`rasterize_glyph`, `load_system_font`, `measure_font`) but doesn't implement the `GlyphRasterizer` trait that the pixel renderer requires. We need to bridge the gap.

The trait requires:
```rust
trait GlyphRasterizer {
    fn rasterize(&mut self, ch: char, font_size_px: f32, bold: bool, italic: bool) -> Option<RasterizedGlyph>;
    fn measure(&mut self, font_size_px: f32) -> MeasuredFontMetrics;
    fn has_glyph(&self, ch: char) -> bool;
    fn load_font(&mut self, data: &[u8], index: u32) -> bool;
}
```

The DirectWrite rasterizer loads by family name (`load_system_font`), not by bytes. We need `load_font` to work with embedded font data as a fallback, but the primary path will be system font loading. We also need bold/italic support via additional font faces.

- [ ] **Step 1: Add bold/italic font face fields and loading**

Add fields for bold, italic, and bold-italic font faces to `DirectWriteRasterizer`. Add a method to load a specific weight/style variant.

In `terminal-surface/src/directwrite_rasterizer.rs`, add these fields to the struct:

```rust
pub struct DirectWriteRasterizer {
    factory: IDWriteFactory,
    font_face: Option<IDWriteFontFace>,
    bold_face: Option<IDWriteFontFace>,
    italic_face: Option<IDWriteFontFace>,
    bold_italic_face: Option<IDWriteFontFace>,
    rendering_params: IDWriteRenderingParams,
    scale_factor: f32,
    /// Cached font family name for has_glyph lookups.
    font_family_name: String,
}
```

Update `new()` to initialize the new fields to `None` and `font_family_name` to `String::new()`.

Update `load_system_font` to also load the bold, italic, and bold-italic faces:

```rust
pub fn load_system_font(&mut self, family_name: &str) -> windows::core::Result<()> {
    unsafe {
        let mut collection: Option<IDWriteFontCollection> = None;
        self.factory
            .GetSystemFontCollection(&mut collection, false)?;
        let collection = collection.ok_or(windows::core::Error::from(E_FAIL))?;

        let mut index = 0u32;
        let mut exists = BOOL::default();
        let family_wide: Vec<u16> = family_name
            .encode_utf16()
            .chain(std::iter::once(0))
            .collect();
        let family_pcwstr = PCWSTR(family_wide.as_ptr());
        collection.FindFamilyName(family_pcwstr, &mut index, &mut exists)?;

        if !exists.as_bool() {
            return Err(windows::core::Error::from(E_FAIL));
        }

        let font_family = collection.GetFontFamily(index)?;

        // Regular
        let regular = font_family.GetFirstMatchingFont(
            DWRITE_FONT_WEIGHT_REGULAR,
            DWRITE_FONT_STRETCH_NORMAL,
            DWRITE_FONT_STYLE_NORMAL,
        )?;
        self.font_face = Some(regular.CreateFontFace()?);

        // Bold (optional ├óΓé¼ΓÇ¥ fall back to regular if not found)
        self.bold_face = font_family
            .GetFirstMatchingFont(
                DWRITE_FONT_WEIGHT_BOLD,
                DWRITE_FONT_STRETCH_NORMAL,
                DWRITE_FONT_STYLE_NORMAL,
            )
            .ok()
            .and_then(|f| f.CreateFontFace().ok());

        // Italic (optional)
        self.italic_face = font_family
            .GetFirstMatchingFont(
                DWRITE_FONT_WEIGHT_REGULAR,
                DWRITE_FONT_STRETCH_NORMAL,
                DWRITE_FONT_STYLE_ITALIC,
            )
            .ok()
            .and_then(|f| f.CreateFontFace().ok());

        // Bold-Italic (optional)
        self.bold_italic_face = font_family
            .GetFirstMatchingFont(
                DWRITE_FONT_WEIGHT_BOLD,
                DWRITE_FONT_STRETCH_NORMAL,
                DWRITE_FONT_STYLE_ITALIC,
            )
            .ok()
            .and_then(|f| f.CreateFontFace().ok());

        self.font_family_name = family_name.to_string();
        Ok(())
    }
}
